  ('pawlaatschnhaus', 'Pawlaatschnhaus', 'das', '', '', 'Wiener Architektur & Baukunst', 'Pawlatschenhaus', '[{"kategorie": "wörtlich", "text": "\"Pawlatschenhaus\" (Determinativkompositum aus [[Pawlatschen]]=\"offener Laubengang auf der Hofseite eines Hauses, der als Zugang zu Wohnungen dient\" und \"Haus\"=\"Wohnhaus\")"}, {"kategorie": "allg.", "text": "\"Haus mit Rundumbalkon im Obergeschoß\", \"Mehrparteienhaus mit umlaufender Galerie\" (Haus mit einer Galerie im Innenhof, zu der eine Stiege hinaufführt und über die vom Hof zugängliche Wohnungen in den Stockwerken erreicht werden können), Arkadenhaus, Haus mit Laubengang"}]'::jsonb, ''),
  ('pawlaatschnsaenga', 'Pawlaatschnsänga', 'der', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Pawlatschensänger', '[{"kategorie": "wörtlich", "text": "\"Pawlatschensänger\" (Determinativkompositum aus [[Pawlatschen]]=\"Bretterbühne im Innenhof eines Arkadenhauses\" und \"Sänger\"=\"Vorstadtsänger\")"}, {"kategorie": "allg.", "text": "\"Sänger, der im Innenhof eines [[Pawlatschenhauses]]\" [Arkadenhauses] auftritt\" (vom tschechischen \"pavlač\"=\"Galerie\" bzw. \"offener Hauseingang\"), Vorstadtsänger, Wirtshaussänger, Wienerliedsänger (der auf einfachen Bretterbühnen im Innenhof von Gasthäusern auftritt)"}]'::jsonb, 'Ea is ka Oopanstaa, owa ois Pawlatschnsänga kennd eam a jeeds Kind im Grätzl!'),
  ('pawlaatschnprimadonna', 'Pawlaatschnprimadonna', 'die', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Pawlatschen-Primadonna', '[{"kategorie": "wörtlich", "text": "\"Pawlatschen-Primadonna\" (Determinativkompositum aus [[Pawlatschen]]=\"Bretterbühne im Innenhof eines Arkadenhauses\" und \"Primadonna\"=\"Operndiva\")"}, {"kategorie": "allg.", "text": "\"Opensängerin, die im Innenhof eines [[Pawlatschenhauses]]\" [Arkadenhauses] auftritt\" (vom tschechischen \"pavlač\"=\"Galerie\" bzw. \"offener Hauseingang\"), Vorstadtdiva, Vorstadtsängerin, Wirtshaussängerin, Wienerliedsängerin (die auf einfachen Bretterbühnen im Innenhof von Gasthäusern auftritt)"}]'::jsonb, ''),
  ('pawlaatschnkonzead', 'Pawlaatschnkonzead', 'das', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Pawlatschenkonzert', '[{"kategorie": "wörtlich", "text": "\"Pawlatschenkonzert\" (Determinativkompositum aus [[Pawlatschen]]=\"Bretterbühne im Innenhof eines Arkadenhauses\" und \"Konzert\"=\"Freiluftkonzert\")"}, {"kategorie": "allg.", "text": "\"Konzert im Innenhof eines [[Pawlatschenhauses]]\" [Arkadenhauses]\" (vom tschechischen \"pavlač\"=\"Galerie\" bzw. \"offener Hauseingang\"), Vorstadtkonzert, Wirtshauskonzert, Wienerliedkonzert (auf einfachen Bretterbühnen im Innenhof von Gasthäusern)"}]'::jsonb, 'A Pawlaatschnkonzead is ned nuara Event - es is a Schdickl gleebda Weana Söö!'),
  ('pawlaatschntischla', 'Pawlaatschntischla', 'der', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Pawlatschentischler', '[{"kategorie": "wörtlich", "text": "\"Pawlatschentischler\" (Determinativkompositum aus [[Pawlatsche]]=\"offener Laubengang auf der Hofseite eines Hauses, der als Zugang zu Wohnungen dient\" und \"Tischler\"=\"Zimmermann\")"}, {"kategorie": "allg.", "text": "\"Tischler, der Pawlatschen [Laubengänge/Galerien/Arkaden] fertigt\"  (vom tschechischen \"pavlač\"=\"Hofgalerie\"), \"Pawlatschenbauer\", \"Arkadenbauer\", \"Hofgaleriebauer\", \"Zimmermann der Innenhöfe\""}, {"kategorie": "scherzhaft für", "text": "Gerüstbauer, Gerüster, \"Gerüstschrauber\", \"Gerüsttischler\" (humorvolle Bezeichnung für Gerüstbauer, deren temporäre Konstruktionen an die klassischen Pawlatschen – die hölzernen Laubengänge in Wiener Innenhöfen – erinnern)"}]'::jsonb, 'Ois eafoarana Pawlaatschntischla kennda a jeeds Detäu von de oidn Laubmgäng - augfaungan bei de Boikn bis hii zua letzdn Schraufn!'),
  ('peckn', 'peckn', '', '', '', 'Grundwortschatz Wienerisch', 'pecken', '[{"kategorie": "wörtlich", "text": "\"mit dem Schnabel hacken\" (vom mittelhochdeutschen \"pecken\"=\"mit dem Schnabel hacken\")"}, {"kategorie": "allg.", "text": "picken, hacken, schlagen, stoßen, [[ditschn]]"}, {"kategorie": "scherzhaft für", "text": "zahlen, berappen, löhnen"}, {"kategorie": "Jugendsprache", "text": "stechen, tätowieren, ein Tattoo stechen"}, {"kategorie": "fig.", "text": "\"auf jemandem herumhacken\",  ständig an jemandem herumnörgeln, jemanden ständig kritisieren, drangsalieren, auf jemanden [[hinpecken]], [[einpecken]]"}, {"kategorie": "sexuell", "text": "\"eine Frau stechen\", \"einen Stich machen\", mit jemandem schlafen, sexuell verkehren, [[pudern]], [[schustern]], [[schnackseln]]"}]'::jsonb, 'Muang loss I ma an Drochn aum Oasch peckn!'),
  ('pecka', 'Pecka', 'der', '', '', 'Grundwortschatz Wienerisch', 'Pecker', '[{"kategorie": "wörtlich", "text": "\"Schnabelhieb\" (vom mittelhochdeutschen [[pecken]]=\"mit dem Schnabel hacken\")"}, {"kategorie": "allg.", "text": "kleine Delle, Schramme, Kratzer, Steinschlagschaden (am Auto, etc.)"}, {"kategorie": "fig.", "text": "Dachschaden, \"Vogel\", [[Hacker]], [[Klopfer]], [[Klescher]], [[Glaumsch]], [[Hirnpecker]]"}, {"kategorie": "scherzhaft für jemanden, der anderen ein Tattoo auf die Haut àpeckt", "text": "Tätowierer, \"Tattoo-Künstler\", [[Schlampenpecker]], [[Arschvignettenpecker]]"}, {"kategorie": "sexuell", "text": "Stich (mit dem Penis), Geschlechtsakt, Liebesakt, \"Ritt\", [[Fahrer]], [[Bumserl]]"}, {"kategorie": "sexuell", "text": "\"Stecher\", \"Frauenstecher\", \"Aufreißer\", \"Röckchenjäger\""}]'::jsonb, 'Da Pecka hod meina Oidn a Oaschgwei peckd - schaud echt aus wia gedruckd!'),
  ('peckal', 'Peckal', 'das', '', '', 'Grundwortschatz Wienerisch', 'Peckerl', '[{"kategorie": "wörtlich", "text": "\"kleiner Schnabelhieb\" (vom mittelhochdeutschen [[pecken]]=\"mit dem Schnabel hacken\")"}, {"kategorie": "Jugendsprache", "text": "kleine Tätowierung,  kleines \"Tattoo\", [[Schlampenpeckerl]], [[Arschvignettenpeckerl]]"}]'::jsonb, 'Des Peckal auf sein Bizeps schaud aus, ois häd eams a Blinda min Löötkoibm gschdochn!'),
  ('eiapeckn', 'Eiapeckn', 'das', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Eierpecken', '[{"kategorie": "wörtlich", "text": "\"Aneinanderschlagen zweier hartgekochter Ostereier\" (vom mittelhochdeutschen \"pecken\"=\"mit dem Schnabel hacken\")"}, {"kategorie": "allg.", "text": "\"Eierstoßen\", [[Eiertitschen]] (österliches Spiel, bei dem derjenige verliert, dessen Ei beim Anstoßen eingedrückt wird)"}]'::jsonb, ''),
  ('eiaditschn', 'Eiaditschn', 'das', '', '', 'Grundwortschatz Wienerisch', 'Eiertitschen', '[{"kategorie": "wörtlich", "text": "\"Aneinanderschlagen zweier hartgekochter Ostereier\" (von [[titschen]]=\"aneinanderschlagen\")"}, {"kategorie": "", "text": "\"Eierstoßen\", [[Eierpecken]] (österliches Spiel, bei dem derjenige verliert, dessen Ei beim Anstoßen eingedrückt wird)"}]'::jsonb, 'Des Eia, wos beim Eiaditschn häu bleibd, is a Symbol fian Sieg vom Leebm iwan Tood!'),
  ('umanaundpeckn', 'umanaundpeckn', '', '', '', 'Grundwortschatz Wienerisch', 'umeinanderpecken', '[{"kategorie": "wörtlich", "text": "\"herumpicken\"  (Kompositum aus dem abtrennbaren Präfix [[umanaund]]=\"herum\" und [[pecken]]=\"mit dem Schnabel hacken\")"}, {"kategorie": "fig.", "text": "herumhacken (auf jemandem), ständig an jemandem herumnörgeln, jemanden ständig kritisieren, drangsalieren, fertigmachen"}]'::jsonb, 'De peckn auf eam umanaund, ois wara da letzte Dreck!'),
  ('umadumpeckn', 'umadumpeckn', '', '', '', 'Grundwortschatz Wienerisch', 'herumpecken', '[{"kategorie": "wörtlich", "text": "\"herumpicken\"  (Kompositum aus dem abtrennbaren Präfix [[umadum]]=\"herum\" und [[pecken]]=\"mit dem Schnabel hacken\")"}, {"kategorie": "fig.", "text": "herumhacken (auf jemandem), ständig an jemandem herumnörgeln, jemanden ständig kritisieren, drangsalieren, fertigmachen"}]'::jsonb, 'Mei Oide peckd auf mia umadum, ois warad I ia peasönlicha Blitzobleita!'),
  ('eipeckn', 'eipeckn', '', '', '', 'Grundwortschatz Wienerisch', 'einpecken', '[{"kategorie": "wörtlich", "text": "\"einhacken\" (Kompositum aus dem abtrennbaren Präfix [[ein]]=\"in etwas hinein\" und [[pecken]]=\"hacken\")"}, {"kategorie": "Fleischhauerjargon", "text": "\"Fleischränder und Sehnen (nach dem Klopfen) leicht einschneiden\", einritzen, einstechen, einhacken"}, {"kategorie": "fig.", "text": "auf jemanden einpecken, hinpecken, an jemandem ständig herumnörgerln, jemanden ständig kritisieren, drangsalieren"}]'::jsonb, 'I tua da de Schnitzln vuaklopfn und eipeckn, daunn brauchsdas nuo no panian!'),
  ('draufpeckn', 'draufpeckn', '', '', '', 'Grundwortschatz Wienerisch', 'draufpecken', '[{"kategorie": "wörtlich", "text": "\"draufpecken\" (Kompositum aus dem abtrennbaren Präfix [[drauf]]=\"auf etwas\" und [[pecken]]=\"hacken\" bzw. \"zahlen\"/\"blechen\")"}, {"kategorie": "allg.", "text": "\"aufzahlen\", \"etwas zusätzlich zahlen\", \"noch etwas obendrauf legen\""}, {"kategorie": "fig.", "text": "auf jemanden einpecken, hinpecken, an jemandem ständig herumnörgerln, jemanden ständig kritisieren, drangsalieren, runterputzen"}]'::jsonb, 'Waunnsd wos Gscheids wüüsd, muassd hoid noo uandlich wos draufpeckn, Bua!'),
  ('wegpeckn', 'wegpeckn', '', '', '', 'Grundwortschatz Wienerisch', 'wegpecken', '[{"kategorie": "wörtlich", "text": "\"wegpecken\" (Determinativkompositum aus dem abtrennbaren Präfix \"weg\"=\"fort\" und dem Verb \"pecken\"=\"picken\")"}, {"kategorie": "allg.", "text": "etwas wegpicken, wegfuttern, \"etwas aufpicken und verschlucken\""}, {"kategorie": "fig.", "text": "jemandem etwas wegschnappen, wegnehmen, abspenstig machen"}]'::jsonb, 'De Taubm haum olle Breesl vom Boodn wegpeckd!'),
  ('zsaummpeckn', 'zsaummpeckn', '', '', '', 'Grundwortschatz Wienerisch', 'zusammenpecken', '[{"kategorie": "wörtlich", "text": "\"zusammenpecken\" (Kompositum aus dem Partikel [[zusammen]]=\"zu einem Ganzen\" und [[pecken]]=\"hacken\")"}, {"kategorie": "allg.", "text": "etwas zusammenhacken, zerhacken, zerkleinern"}, {"kategorie": "fig.", "text": "\"jemanden zusammenstutzen\", auseinandernehmen, niedermachen, \"auf jemandem gnadenlos herumhacken\""}]'::jsonb, 'In Peedasüü kaunnsd ruhig grob zsaummpeckn - dea kummd ää nua ois Deko oobm drauf!'),
  ('schlaumpnpecka', 'Schlaumpnpecka', 'der', '', '', 'Echte Wiener Schmähperlen', 'Schlampenpecker', '[{"kategorie": "wörtlich", "text": "\"Schlampenpecker\" (Determinativkompositum aus \"Schlampe\"=\"Tussi\" und \"Pecker\"=\"Tätowierer\")"}, {"kategorie": "scherzhaft für", "text": "\"Steißbeinstecher\", \"Arschgeweih-Pecker\", \"Trampstamp-Tätowierer\", \"Popo-Pikser\" (Tätowierer, der einer Frau das ''Schlampensymbol'' [Arschgeweih] knapp oberhalb des Steißbeins ''peckt'' [sticht]), [[Arschgeweihstempler]], [[Arschvignettenstempler]]"}]'::jsonb, 'Mei Oide hod si von so an Schlaumpnpecka a Oaschgwei aum Hintan schdechn lossn!'),
  ('schlaumpnpeckal', 'Schlaumpnpeckal', 'das', '', '', 'Echte Wiener Schmähperlen', 'Schlampenpeckerl', '[{"kategorie": "wörtlich", "text": "\"Schlampenpeckerl\" (Determinativkompositum aus \"Schlampe\"=\"Tussi\" und \"Peckerl\"=\"Tattoo\")"}, {"kategorie": "scherzhaft für", "text": "\"Arschgeweih-Tattoo\" (\"Tätowierung in Form des ''Schlampensymbols'' [Arschgeweih], das einer Frau vom Tätowierer knapp oberhalb des Steißbeins ''gepeckt'' [gestochen] wird\"), \"Steißbein-Tribal\", \"Hüft-Tattoo\" (\"Lower-Back-Tattoo\"  auf dem unteren Rücken bei Frauen\"),  \"Popo-Tattoo\", [[Arschvignettenstempel]], [[Arschgeweihstempel]]"}]'::jsonb, 'Si is ausn Ualaub zruck - frisch gebräund und mit an Schlaumpnpeckal iwan Oasch, des leicht wiara Bauschdöönschüüd!'),
  ('oaschwinjettnpeckal', 'Oaschwinjettnpeckal', 'das', '', '', 'Echte Wiener Schmähperlen', 'Arschvignettenpeckerl', '[{"kategorie": "wörtlich", "text": "\"Arschvignettenpeckerl\" (Determinativkompositum aus \"Arschvignette\"=\"Steißbein-Tribal\" und \"Peckerl\"=\"Tattoo\")"}, {"kategorie": "scherzhaft für", "text": "\"Arschgeweih-Tattoo\" (\"Tätowierung in Form eines Arschgeweihs, das einer Frau vom Tätowierer knapp oberhalb des Steißbeins ''gepeckt'' [gestochen] wird\"), \"Steißbein-Tribal\", \"Hüft-Tattoo\" (\"Lower-Back-Tattoo\"  auf dem unteren Rücken bei Frauen\"),  \"Popo-Tattoo\", [[Arschgeweihstempel]], [[Schlampenpeckerl]]"}]'::jsonb, 'A Oaschwinjettnpeckal is wiara schlechta Ex - es geed nimma weg, owa olle seengs!'),
  ('oaschwinjettnpecka', 'Oaschwinjettnpecka', 'der', '', '', 'Echte Wiener Schmähperlen', 'Arschvignettenpecker', '[{"kategorie": "wörtlich", "text": "\"Arschvignettenpecker\" (Determinativkompositum aus \"Arschvignette\"=\"Zierbild auf dem Hintern\" und \"Pecker\"=\"Tätowierer\")"}, {"kategorie": "scherzhaft für", "text": "\"Steißbeinstecher\", \"Arschgeweih-Pecker\", \"Trampstamp-Tätowierer\", \"Popo-Pikser\" (Tätowierer, der einer Frau das ''Arschvignettensymbol'' [Arschgeweih] knapp oberhalb des Steißbeins ''peckt'' [sticht]), [[Arschgeweihstempler]], [[Schlampenstempler]]"}]'::jsonb, 'Dea Oaschwinjettnpecka hod ia a Schlaumpn-Tattuu gritzd - jetzd rennds umanaund wiara Tussi aus de 90-a!'),
  ('oaschgweischpeckal', 'Oaschgweischpeckal', 'das', '', '', 'Echte Wiener Schmähperlen', 'Arschgeweihpeckerl', '[{"kategorie": "wörtlich", "text": "\"Arschgeweihpeckerl\" (Determinativkompositum aus \"Arschgeweih\"=\"Steißbein-Tribal\" und \"Peckerl\"=\"Tattoo\")"}, {"kategorie": "scherzhaft für", "text": "\"Arschgeweih-Tattoo\" (\"Tätowierung in Form eines Arschgeweihs, das einer Frau vom Tätowierer knapp oberhalb des Steißbeins ''gepeckt'' [gestochen] wird\"), \"Steißbein-Tribal\", \"Hüft-Tattoo\" (\"Lower-Back-Tattoo\"  auf dem unteren Rücken bei Frauen\"),  \"Popo-Tattoo\", [[Arschgeweihstempel]], [[Schlampenpeckerl]]"}]'::jsonb, ''),
  ('oaschgweipecka', 'Oaschgweipecka', 'der', '', '', 'Echte Wiener Schmähperlen', 'Arschgeweihpecker', '[{"kategorie": "wörtlich", "text": "\"Arschgeweihpecker\" (Determinativkompositum aus \"Arschgeweih\"=\"Steißbein-Tribal\" und \"Pecker\"=\"Tätowierer\")"}, {"kategorie": "scherzhaft für", "text": "\"Steißbeinstecher\", \"Arschgeweih-Pecker\", \"Trampstamp-Tätowierer\", \"Popo-Pikser\" (Tätowierer, der einer Frau das ''Arschvignettensymbol'' [Arschgeweih] knapp oberhalb des Steißbeins ''peckt'' [sticht]), [[Arschvignettenstempler]], [[Schlampenstempler]]"}]'::jsonb, 'Da Oaschgweipecka is quasi da Schlaumpnschdecha aus de 90-a - kaane wüüs zuageem, owa fost jeede woa moi do!'),
  ('peitschalbua', 'Peitschalbua', 'der', '', '', 'Echte Wiener Schmähperlen', 'Peitscherlbube', '[{"kategorie": "wörtlich", "text": "\"Peitscherlbub\" (Determinativkompositum aus \"Peitscherl\"=\"kleine Peitsche\" und \"Bua\"=\"Junge\")"}, {"kategorie": "Gaunersprache", "text": "\"Peitscherlbub\" (\"der Junge, der seine Huren mit der Peitsche auf den [[Strich]] treibt\"), \"Zuhälter\"  \"Halbweltler\", [[Strizzi]], [[Halbseidener]], [[Grammeltreiber]], [[Heisl-Louis]]"}]'::jsonb, ''),
  ('peleriin', 'Peleriin', 'die', '', '', 'Grundwortschatz Wienerisch', 'Pelerine', '[{"kategorie": "wörtlich", "text": "\"Pelerine\" (vom französischen \"pèlerine\"=\"von Pilgern getragener Umhang\")"}, {"kategorie": "allg.", "text": "\"Schulterumhang\" (weiter, ärmelloser Umhang), ärmelloser Regenmantel, Regenschutz (wird über der eigentlichen Kleidung getragen und lässt sich in der Regel sehr klein zusammenlegen), [[Reenghaut]], [[Weedahex]]"}]'::jsonb, 'De Peleriin pickd eam wiara a nossa Sock aum Oasch - owa Hauptsoch trockn!'),
  ('perron', 'Perron', 'der', '', '', 'Grundwortschatz Wienerisch', 'Perron', '[{"kategorie": "wörtlich", "text": "\"Perron\" (vom französischen \"perron\"=\"freie Plattform\")"}, {"kategorie": "allg.", "text": "Bahnsteig, Bahnsteigkante, Abfertigungsrampe"}]'::jsonb, 'Zwischn Perron und Gleis liigd a tooda Voogl!'),
  ('petschian', 'petschian', '', '', '', 'Grundwortschatz Wienerisch', 'petschieren', '[{"kategorie": "wörtlich", "text": "\"mit Petschaft siegeln\" (\"Petschaft\"=\"Siegelstempel\", der einen Abdruck in Wachs hinterlässt - vom tschechischen \"pečat\"=\"Stempel\")"}, {"kategorie": "hist.", "text": "stempeln, siegeln (indem man mit dem Petschaft Abdrücke in Wachs oder anderen Materialien hinterlässt), \"mit einem Siegelstempel versehen\", \"mit Siegelwachs beglaubigen\", \"versiegeln\""}, {"kategorie": "fig.", "text": "\"jemanden mit dem Stempel eines Versagers behaften\", \"jemandes Schicksal besiegeln\", jemanden brandmarken, bloßstellen, blamieren"}, {"kategorie": "in Bezug auf Frauen, scherzhaft für \"mit einem Schwangerschaftsstempel versehen\"", "text": "jemanden schwängern, einer Frau ein Kind machen, ein Kind mit jemandem zeugen, einer Frau ein Kind [[andrehen]]"}]'::jsonb, 'Friara is a jeeds keenigliche Edikt vom Kanzleischreiwa soagföötich aufgroid und mit an roodn Wochs petschiad wuan!'),
  ('petschiad', 'petschiad', '', '', '', 'Grundwortschatz Wienerisch', 'petschiert', '[{"kategorie": "wörtlich", "text": "\"mit einem Petschaft gesiegelt\" (\"Petschaft\"=\"Siegelstempel\", der einen Abdruck in Wachs hinterlässt - vom tschechischen \"pečat\"=\"Stempel\");  2.(allg.)  gestempelt, \"mit einem Siegel versehen\", gesiegelt, versiegelt"}, {"kategorie": "fig.", "text": "\"mit dem Stempel des Versagens behaftet\", gebrandmarkt, bloßgestellt"}, {"kategorie": "in Bezug auf Frauen, scherzhaft im Sinne von \"mit einem Schwangerschaftsstempel versehen\"", "text": "schwanger, geschwängert, in anderen Umständen, [[angestochen]], [[angegitscht]], [[autritschkad]]"}]'::jsonb, 'Nooch den peinlichn Auftritt woara fia olle Zeitn petschiad - ois inkompetenta Daumpfplaudara!'),
  ('pfandl', 'Pfandl', 'das', '', '', 'Grundwortschatz Wienerisch', 'Pfandl', '[{"kategorie": "wörtlich", "text": "\"Pfanne\" (vom althochdeutschen \"pfanna\"=\"Pfanne\")"}, {"kategorie": "allg.", "text": "\"Bratpfanne\" (flaches Küchengerät zum Braten von Fisch, Fleisch, Kartoffeln, etc. auf dem Herd), Edelstahlpfanne, Teflonpfanne, (Baujargon, auch:) \"Maurerpfanne\", etc."}, {"kategorie": "allg., Kurzform für", "text": "\"Pfandleihe\", \"Pfandhaus\", \"Pfandleihanstalt\""}, {"kategorie": "hist., Spitzname für", "text": "Wiener Dorotheum (größtes Wiener Auktionshaus), [[Tante Dorothee]], [[Tante]] Dorli"}]'::jsonb, 'Wos da Wiina ned brauchd, liigd im Pfandl - bisas doch wiida brauchd!'),
  ('babaa', 'Babaa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Babaa', '[{"kategorie": "wörtlich, eingedeutsche Dialektform für", "text": "\"Bye-bye!\" (vom englischen \"Good-bye\" = [verkürzt für]: \"God be with ye\"=\"Gott sei mit dir!\" [religiöser Abschiedsgruß])"}, {"kategorie": "allg., Abschiedsgruß unter Freunden und Verwandten", "text": "\"Leb wohl!\"  3. \"Mach''s gut!\"  4. \"Man sieht sich!\"  5. \"Bis bald!\"  6. \"Ciao!\"  7. \"Tschüssi!\""}]'::jsonb, 'Babaa und foi ned!'),
  ('babaatschi', 'Babaatschi!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Babatschi!', '[{"kategorie": "wörtlich", "text": "\"Babatschi!\" (Diminutiv von [[Babaa!]], eingedeutsche Dialektform vom englischen \"Bye-bye\" = [verkürzt für]: \"Good-bye\"=\"God be with ye\"=\"Gott sei mit dir!\")"}, {"kategorie": "allg., Abschiedsgruß unter Freunden und Verwandten", "text": "\"Tschüssi!\" 3. [[Pfiat]] di!  4. Ciao!  5. Bye!  6. Peace Out!"}]'::jsonb, 'Babaatschi, Mamaatschi!'),
  ('seawas', 'Seawas!', '', '', '', 'Grundwortschatz Wienerisch', 'Servus!', '[{"kategorie": "wörtlich", "text": "\"Servus!\" (vom lateinischen \"servus\"=\"Diener\", als Grußformel ursprünglich in der Bedeutung \"Ihr Diener!\" - wie beispielsweise in der Höflichkeitsfloskel \"Servus humillimus!\"=\"Ihr untertänigster Diener!“)"}, {"kategorie": "allg., Grußformel - früher gegenüber Vorgesetzten, heute unter Freunden", "text": "\"Hallo!\"; \"Schön dich zu sehen!\";  [[Salve!]]; [[Griass di!]]; [[Hawedeere!]]"}, {"kategorie": "Ausruf des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "\"Du liebe Zeit!\"; \"Ach, herrje!\";  \"Mannomann!\"; \"Du meine Güte!\"; \"Himmel noch mal!\"; \"Alter Schwede!\"; \"Mein lieber Schwan!\"; [[Na bumm!]]; [[Marantana!]]; [[Heiliger Bimbam!]]; [[Nau seawas!]]; à\"Jössasnaa!"}]'::jsonb, 'Seawas, wos hobds jetzt wiida augschdööd?!'),
  ('salve', 'Salve!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Salve!', '[{"kategorie": "wörtlich", "text": "\"Salve!\" (vom lateinischen \"Salve!\"=\"Sei gegrüßt!\")"}, {"kategorie": "scherzhafte Grußformel unter Freunden", "text": "\"Sei gegrüßt!\"; [[Servus!]]; [[Griass di!]]; [[Hawedeere!]]"}]'::jsonb, 'Salve, oida Rööma - wos mochd''s Imperium?'),
  ('seeas', 'Seeas!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Seeas!', '[{"kategorie": "wörtlich", "text": "\"Seeas!\" (jugendsprachliche Verkürzung von \"Servus\" - vom lateinischen \"servus\"=\"Diener\", als Grußformel ursprünglich in der Bedeutung \"Ihr Diener!\" - wie beispielsweise in der Höflichkeitsfloskel \"Servus humillimus!\"=\"Ihr untertänigster Diener!“)"}, {"kategorie": "allg., Grußformel unter Du-Freunden sowohl zur Begrüßung als auch zur Verabschiedung", "text": "\"Hallo!\"; [[Salve!]]; [[Griass di!]]; [[Hawedeere!]]"}, {"kategorie": "Ausruf des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "\"Du liebe Zeit!\"; \"Ach, herrje!\";  \"Mannomann!\"; \"Du meine Güte!\"; \"Heilige Scheiße!\"; \"Himmel noch mal!\"; \"Alter Schwede!\"; \"Mein lieber Schwan!\"; [[Na bumm!]]; [[Marantana!]]; [[Heiliger Bimbam!]]; [[Nau seawas!]]; à\"Jössasnaa!"}]'::jsonb, 'Seeas, waunnsd do Gas gibsd, hauds da in Oasch ins Handschuachfachl!'),
  ('dideere', 'Dideere!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Dir d''Ehre!', '[{"kategorie": "wörtlich, Kurzform für den Gruß", "text": "\"Dir die Ehre!\" (Grußformel, die sich aus der Höflichkeitsfloskel \"Ich habe die Ehre\" entwickelte, welche früher besonders im militärischen und adligen Umfeld üblich war)"}, {"kategorie": "allg., Grußformel - früher gegenüber Vorgesetzten, heute unter Freunden", "text": "\"Schön dich zu sehen!\"; \"Servus!\"; \"Hallo, mein Freund!\"; [[Griass di!]]; [[Tschau Kakau!]]"}, {"kategorie": "Ausruf des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "\"Du liebe Zeit!\"; \"Ach, herrje!\";  \"Mannomann!\"; \"Du meine Güte!\"; \"Himmel noch mal!\"; \"Alter Schwede!\"; \"Mein lieber Schwan!\"; [[Na bumm!]]; [[Marantana!]]; [[Heiliger Bimbam!]]; [[Nau seawas!]]; à\"Jössasnaa!"}]'::jsonb, 'Dideere, oide Hittn!'),
  ('deere', 'Deere!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'D''Ehre!', '[{"kategorie": "wörtlich, Kurzform für den Gruß", "text": "\"Habe die Ehre!\" (Grußformel, welche früher besonders im militärischen und adligen Umfeld üblich war)"}, {"kategorie": "allg., Grußformel - früher gegenüber Vorgesetzten, heute unter Freunden", "text": "\"Schön dich zu sehen!\"; \"Servus!\"; \"Hallo, mein Freund!\"; [[Griass di!]]; [[Tschau Kakau!]]"}, {"kategorie": "Ausruf des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "\"Du liebe Zeit!\"; \"Ach, herrje!\";  \"Mannomann!\"; \"Du meine Güte!\"; \"Himmel noch mal!\"; \"Alter Schwede!\"; \"Mein lieber Schwan!\"; [[Na bumm!]]; [[Marantana!]]; [[Heiliger Bimbam!]]; [[Nau seawas!]]; à\"Jössasnaa!"}]'::jsonb, 'Deere, Oida!'),
  ('djeere', 'Djeere!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'D''Ehre!', '[{"kategorie": "wörtlich, Kurzform für den Gruß", "text": "\"Habe die Ehre!\" (Grußformel, welche früher besonders im militärischen und adligen Umfeld üblich war)"}, {"kategorie": "allg., Grußformel - früher gegenüber Vorgesetzten, heute unter Freunden", "text": "\"Schön dich zu sehen!\"; \"Servus!\"; \"Hallo, mein Freund!\"; [[Griass di!]]; [[Tschau Kakau!]]"}, {"kategorie": "Ausruf des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "\"Du liebe Zeit!\"; \"Ach, herrje!\";  \"Mannomann!\"; \"Du meine Güte!\"; \"Himmel noch mal!\"; \"Alter Schwede!\"; \"Mein lieber Schwan!\"; [[Na bumm!]]; [[Marantana!]]; [[Heiliger Bimbam!]]; [[Nau seawas!]]; à\"Jössasnaa!"}]'::jsonb, 'Djeere, es Beidln!'),
  ('hawedeere', 'Hawedeere!', '', '', '', 'Grundwortschatz Wienerisch', 'Habe die Ehre', '[{"kategorie": "wörtlich", "text": "Habe die Ehre! (ursprünglich ein Gruß, der gegenüber ranghöheren Personen verwendet wurde, Kurzform für \"Ich habe die Ehre, mit ihnen sprechen zu dürfen!\")"}, {"kategorie": "heute Grußformel unter Freunden", "text": "[[Servus!]] [[Griass di!]], [[Deere!]], [[Tschau Kakau!]]"}, {"kategorie": "Ausruf des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "\"Du liebe Zeit!\"; \"Ach, herrje!\""}, {"kategorie": "", "text": "\"Mannomann!\"; \"Du meine Güte!\"; \"Himmel noch mal!\"; \"Alter Schwede!\"; [[Marantana]]! [[Heiliger]] Bimbam! [[Nau]] seawas! [[Jössasnaa]]!"}]'::jsonb, ''),
  ('hawediina', 'Hawediina!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Habediena!', '[{"kategorie": "wörtlich", "text": "\"Habe Diener!\" (Ausruf der Resignation, verballhornte Kontraktion von \"Habe die Ehre!\" und \"Gehorsamster Diener\")"}, {"kategorie": "", "text": "\"Du liebe Zeit!\"  3. \"Mein lieber Schwan!\"  4. \"Herrgott noch mal!\"  5. \"Du meine Güte!\"  6. \"Alter Schwede!\";  7.[[Marantana!]]  8.[[Heiliger]] Bimbam!  9.[[Nau seawas!]] [[Jössasnaa!]]"}]'::jsonb, 'Hawediina, jetzt samma im Oasch dahaam!'),
  ('tschau', 'Tschau!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ciao!', '[{"kategorie": "wörtlich", "text": "\"Tschau\" (eingedeutsche Form des italienischen \"Ciao!\"=[[Servus!]] = eigtl. \"Ihr Diener!\" - vom venezianischen \"sciao\", einer Nebenform des italienischen \"schiavo\"=\"Sklave\")"}, {"kategorie": "Jugendsprache, Abschiedsgruß", "text": "[[Servus!]]  3. [[Pfiat di Good!]]  4. [[Tschüssikowski]]!\"  5. [[Tschaui!]]  6. [[Babaatschi!]]  7. [[Babaa und foi ned!]]  8. [[Pfiat di Good, du oide Krood!]]"}]'::jsonb, ''),
  ('tschaui', 'Tschaui!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ciaoi!', '[{"kategorie": "wörtlich", "text": "\"Tschaui\" (Diminutiv von \"Tschau\" = eingedeutsche Form des italienischen \"Ciao!\"=[[Servus!]] = eigtl. \"Ihr Diener!\" - vom venezianischen \"sciao\", einer Nebenform des italienischen \"schiavo\"=\"Sklave\")"}, {"kategorie": "Jugendsprache, Abschiedsgruß", "text": "[[Servus!]]  3. [[Pfiat di Good!]]  4. [[Tschüssikowski]]!\"  5. [[Tschaui!]]  6. [[Babaatschi!]]  7. [[Babaa und foi ned!]]  8. [[Pfiat di Good, du oide Krood!]]"}]'::jsonb, 'Tschüss mit ü!'),
  ('tschuess', 'Tschüss!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Tschüss!', '[{"kategorie": "wörtlich", "text": "\"Tschüss!\" (vom spanischen \"A dios!\"=\"Zu Gott!\" - Im 17. Jahrhundert übernahmen Seeleute und Händler im norddeutschen Raum das französische \"A dios\", woraus im Niederdeutschen dann \"adjüs\" und schließlich durch lautliche Abschleifung und Vereinfachung die vertrautere Form \"tschüss\" wurde)"}, {"kategorie": "Jugendsprache, als Abschiedsgruß", "text": "[[Pfiat di Good!]]  3. [[Tschüssikowski]]!\"  4. [[Tschaui!]]  5. [[Babaatschi!]]  6. [[Babaa und foi ned!]]  7. \"Pfiat di Good, du oide Krood!\""}]'::jsonb, 'Tschüss mit ü!'),
  ('tschuessi', 'Tschüssi!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Tschüssi!', '[{"kategorie": "wörtlich", "text": "\"Tschüssi!\" (Diminutiv von \"tschüss\" - Abschiedsgruß, abgeleitet vom spanischen \"A dios!\"=\"Zu Gott!\" - Im 17. Jahrhundert übernahmen Seeleute und Händler im norddeutschen Raum das französische \"A dios\", woraus im Niederdeutschen dann \"adjüs\" und schließlich durch lautliche Abschleifung und Vereinfachung die vertrautere Form \"tschüss\" wurde)"}, {"kategorie": "Jugendsprache, Abschiedsgruß", "text": "\"Tschüss!\"  3. \"Tschüss mit ü!\"  4. \"Tschüssikowski!\"  5. \"Tschaui!\"  6. [[Babaatschi!]]  7. [[Babaa und foi ned!]]  8. \"Pfiat di Good, du oide Krood!\""}]'::jsonb, ''),
  ('tschuessikowksi', 'Tschüssikowksi!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Tschüssikowksi!', '[{"kategorie": "wörtlich", "text": "\"Tschüssikowkski!\" (Nonsensbildung von \"tschüss\" - Abschiedsgruß, abgeleitet vom spanischen \"A dios!\"=\"Zu Gott!\" - Im 17. Jahrhundert übernahmen Seeleute und Händler im norddeutschen Raum das französische \"A dios\", woraus im Niederdeutschen dann \"adjüs\" und schließlich durch lautliche Abschleifung und Vereinfachung die vertrautere Form \"tschüss\" wurde)"}, {"kategorie": "Jugendsprache", "text": "\"Tschüss!\"  3. \"Tschüss mit ü!\"  4. [[Babaatschi!]]  5. [[Babaa und foi ned!]]  6. \"Pfiat di Good, du oide Krood!\""}]'::jsonb, ''),
  ('hearichtn', 'hearichtn', '', '', '', 'Grundwortschatz Wienerisch', 'herrichten', '[{"kategorie": "wörtlich", "text": "\"herrichten\" (Kompositum aus dem abtrennbaren Präfix \"her\"=\"herzu\" und \"richten\"=\"in Ordnung bringen\""}, {"kategorie": "allg.", "text": "vorbereiten, bereitstellen, parat halten"}, {"kategorie": "techn.", "text": "zurechtrichten, \"auf Vordermann bringen\", reparieren, instandsetzen"}, {"kategorie": "Küchenjargon", "text": "zubereiten, anrichten, auftischen"}, {"kategorie": "reflexiv", "text": "\"sich herrichten\", \"sich zurechtmachen\", \"sich fertigmachen\", \"sich aufhübschen\", \"sich stylen\""}, {"kategorie": "fig.", "text": "jemanden zurichten, betrunken machen, \"abfüllen\", \"volltanken\", (auch): jemanden zusammenschlagen, verprügeln, zusammenkloppen, [[verpleschen]]"}]'::jsonb, 'Richt ollas hea fian Ualaub, owa bitte ned wiida in gaunzn Hausschdaund!'),
  ('pflanzn', 'pflanzn', '', '', '', 'Grundwortschatz Wienerisch', 'pflanzen', '[{"kategorie": "wörtlich", "text": "\"pflanzen\" (vom mittelhochdeutschen \"pflanzen\"=\"pflanzen\")"}, {"kategorie": "bot., allg.", "text": "\"zum Anwachsen einsetzen\" (Setzlinge oder Samen in die Erde bringen), anpflanzen, aussäen"}, {"kategorie": "fig., vom mittelhochdeutschen \"pflanzen\"=\"etwas/jemanden irgendwo hinstellen\" [hieraus entwickelte sich umgangssprachlich: \"jemanden vor anderen hinstellen\", \"jemanden ausliefern\", \"jemanden der Lächerlichkeit preisgeben\"]", "text": "jemanden frotzeln, hänseln, vorführen, aufziehen, sich über jemanden lustig machen, jemanden lächerlich machen, jemanden zum Narren halten, jemanden verarschen, verhöhnen,  verschaukeln,  [[häkerln]], [[papierln]], [[vaheanzn]]"}]'::jsonb, 'Pflanzn kaunnsd wem aundan, owa ned mi!'),
  ('fitschigoogaln', 'fitschigoogaln', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'fitschigogerln', '[{"kategorie": "Schülerjargon", "text": "\"Fitschigogerl spielen\" (Kompositum aus [[fitschen]]=\"schnell dahingleiten\" und [[gogerln]]=\"hin- und herschaukeln\")"}, {"kategorie": "allg.", "text": "\"Münz-Fingerfußball spielen\" (mit Münzen [Gogerln] und Lineal auf einer Tischplatte, wobei an jedem Tischende jeweils ein Tor durch Ankleben von Kugelschreiberkappen o.ä. markiert wird),  \"Tischhockey-Fußball mit Münzen spielen\", \"Fingerfußball mit Münzen spielen\""}, {"kategorie": "sexuell, \"jemandem die Eier [à\"Gogerln\"] schaukeln", "text": "bumsen, vögeln, [[pudern]], [[nageln]], [[schustern]], [[schnackseln]]"}]'::jsonb, 'Friara hauma in da Schui schdundlaung fitschigoogald - a TZ-Dreieck, drei Münzn, und los geeds!'),
  ('pfitschigoogaln', 'pfitschigoogaln', '', '', '', 'Grundwortschatz Wienerisch', 'pfitschigogerln', '[{"kategorie": "Schülerjargon", "text": "\"Pfitschigogerl spielen\" (Kompositum aus [[pfitschen]]=\"schnell dahingleiten\" und [[gogerln]]=\"hin- und herschaukeln\")"}, {"kategorie": "allg.", "text": "\"Münz-Fingerfußball spielen\" (mit Münzen [Gogerln] und Lineal auf einer Tischplatte, wobei an jedem Tischende jeweils ein Tor durch Ankleben von Kugelschreiberkappen o.ä. markiert wird),  \"Tischhockey-Fußball mit Münzen spielen\", \"Fingerfußball mit Münzen spielen\""}, {"kategorie": "sexuell, \"jemandem die Eier [à\"Gogerln\"] schaukeln", "text": "bumsen, vögeln, [[pudern]], [[nageln]], [[schustern]], [[schnackseln]]"}]'::jsonb, 'Friara hauma in da Schui schdundlaung pfitschigoogald - a TZ-Dreieck, drei Münzn, und los geeds!'),
  ('pflostahiasch', 'Pflostahiasch', 'der', '', '', 'Echte Wiener Schmähperlen', 'Pflasterhirsch', '[{"kategorie": "wörtlich, hist.", "text": "\"Pflasterhirsch\" (Determinativkompositum aus \"Pflaster\"=\"Straßenpflaster\" und \"Hirsch\"=(scherzhaft für): \"Pferd\")"}, {"kategorie": "hist.", "text": "\"Einspännerpferd\" (Pferd, das ein kleines Fuhrwerk [[[Einspänner]]] in der Stadt über das Straßenpflaster zog), Zugpferd, Kutschpferd"}, {"kategorie": "Gaunerjargon", "text": "\"Patrouillenhengst\", \"Polizist auf Fußstreife\", Streifenpolizist (\"der das Straßenpflaster abschreitet\"), Straßenpolizist, [[Polyp]], [[Spinatwachter]], [[Krautwochta]], [[Greana]], [[Gschööda]]"}, {"kategorie": "scherzhaft für", "text": "\"Straßenhure\", \"Sexarbeiterin am Straßenstrich\" (die ihr Revier auf dem Kopfsteinpflaster abschreitet), \"Strichmädchen\", \"Trottoirlady\", \"Bordsteinschwalbe\", [[Asphaltschwalbe]], [[Gürtelschnalle]]"}]'::jsonb, 'Da Pflostahiasch schbringd nua noo, waunns a Fuada gibd!'),
  ('pflostadreeda', 'Pflostadreeda', 'der', '', '', 'Echte Wiener Schmähperlen', 'Pflastertreter', '[{"kategorie": "wörtlich", "text": "\"Plastertreter\" (Determinativkompositum aus \"Pflaster\"=\"Kopfsteinpflaster\" und \"Treter\"=\"Zufußgehender\")"}, {"kategorie": "allg.", "text": "Fußgänger, Spaziergänger, \"Schuhsohlentourist\", \"Asphaltwanderer\""}, {"kategorie": "fig.", "text": "Müßiggänger, Straßengänger, Straßenbummler, \"Asphaltflaneur\", \"Stadtwanderer\""}]'::jsonb, 'De Pflostadreeda in da Siti hoidn in Zebraschdraafn fia eanan Kätwook!'),
  ('pflostara', 'Pflostara', 'der', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Pflasterer', '[{"kategorie": "wörtlich", "text": "\"Pflasterer\" (vom mittelhochdeutschen \"pflaster\"=\"Straßenbelag\")"}, {"kategorie": "allg.", "text": "\"Steinsetzer\", Pflasterarbeiter, Steinplattenleger, Pflasterbauer"}]'::jsonb, 'De Pflostara valeeng aum Toog de Schdaana und aufd Nochd si sööwa - meistns untan Wiadshaustisch!'),
  ('asfaltschwoibm', 'Asfaltschwoibm', 'die', '', '', 'Echte Wiener Schmähperlen', 'Asphaltschwalbe', '[{"kategorie": "wörtlich", "text": "\"Asphaltschwalbe\" (Determinativkompositum aus \"Asphalt\"=\"Straßenbelag\" und \"Schwalbe\"=\"flatterhafte Frau\")"}, {"kategorie": "allg.", "text": "\"Strichmädchen\" (das auf den Straßenstrich geht), Straßenhure, \"Trottoirlady\", \"Strichhuhn\", [[Gürtelschnalle]], [[Bordsteinschwalbe]], [[Pflasterhirsch]], [[Pferderl]], [[Sittich]]"}]'::jsonb, 'Do untn flattan wiida de Asfaltschwoibm umanaund - ois warad Häppi Aua aum Schdrossnschdrich!'),
  ('fitschipfaeu', 'Fitschipfäu', 'der', '', '', 'Grundwortschatz Wienerisch', 'Fitschipfeil', '[{"kategorie": "wörtlich", "text": "\"Fitschipfeil\" (Determinativkompositum aus \"Fitschi\"=\"Flitze\" und \"Pfeil\"=\"Pfeilgeschoss\")"}, {"kategorie": "allg.", "text": "\"Flitzepfeil\" (\"von einem Bogen abgeschossener Pfeil\"), \"Pfeil des Flitzebogens\" (meist aus Weidenholz, Haselruten, etc.), \"Pfeilgeschoss\""}, {"kategorie": "fig.", "text": "\"Flitzekind\" (überaus lebendiges und pfeilschnell herumflitzendes Kind), Wirbelwind, \"Duracell-Kind\", \"Flitzerchen\""}]'::jsonb, 'De Buama haum si Fitschipfäu aus Hooslruudn gschnitzd!'),
  ('pfitschipfaeu', 'Pfitschipfäu', 'der', '', '', 'Grundwortschatz Wienerisch', 'Pfitschipfeil', '[{"kategorie": "wörtlich", "text": "\"Pfitschipfeil\" (Determinativkompositum aus \"Pfitschi\"=\"Flitze\" und \"Pfeil\"=\"Pfeilgeschoss\")"}, {"kategorie": "allg.", "text": "\"Flitzepfeil\" (\"von einem Bogen abgeschossener Pfeil\"), \"Pfeil des Flitzebogens\" (meist aus Weidenholz, Haselruten, etc.), \"Pfeilgeschoss\""}, {"kategorie": "fig.", "text": "\"Flitzekind\" (überaus lebendiges und pfeilschnell herumflitzendes Kind), Wirbelwind, \"Duracell-Kind\", \"Flitzerchen\""}]'::jsonb, 'De Buama haum si Pfitschipfäu aus Hooslruudn gschnitzd!'),
  ('futsch', 'futsch', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'futsch', '[{"kategorie": "wörtlich", "text": "\"nicht mehr da\" (vom jiddischen \"futschn\"=\"verschwinden\" bzw. \"verlorengehen\")"}, {"kategorie": "allg.", "text": "fort, weg, verschwunden, [[pfutsch]], [[heidipritsch]], [[pfutschikato]], [[futschijama]]"}, {"kategorie": "techn.", "text": "verloren, kaputt, im Eimer, \"hinüber\""}]'::jsonb, 'Mei gaunzes Gööd is futsch!'),
  ('pfutsch', 'pfutsch', '', '', '', 'Grundwortschatz Wienerisch', 'pfutsch', '[{"kategorie": "wörtlich", "text": "\"nicht mehr da\" (vom jiddischen \"futschn\"=\"verschwinden\" bzw. \"verlorengehen\")"}, {"kategorie": "allg.", "text": "fort, weg, verschwunden, [[pfutsch]], [[heidipritsch]], [[pfutschikato]], [[futschijama]]"}, {"kategorie": "techn.", "text": "verloren, kaputt, im Eimer, \"hinüber\""}]'::jsonb, 'Des Wuat foit ma ned ei, des is aafoch pfutsch!'),
